use Vaulter\Tests\TestCase;
use Vaulter\Tests\Webhooks\WebhookTestHelpers;

uses(TestCase::class, RefreshDatabase::class);

it('does not delete an outbox row that replay moved back to pending between select and delete', function (): void {
    Carbon::setTestNow('2026-06-30 12:00:00');

    $row = WebhookTestHelpers::outbox([
        'event_id' => 'legacy-race',
        'status' => 'completed',
        'legacy_fanout' => true,
        'delivery_count' => 0,
        'fanned_out_at' => Carbon::now()->subDays(40),
        'fanout_cursor' => null,
        'claim_token' => null,
        'claim_until' => null,
    ]);
    $id = $row->getKey();

    $statusAtDelete = null;
    $deleteSql = null;
    DB::connection()->beforeExecuting(function (string $query) use (&$statusAtDelete, &$deleteSql, $id): void {
        $sql = strtolower($query);
        if (!str_contains($sql, 'delete') || !str_contains($sql, 'outbox')) {
            return;
        }

        // The other operator's replay commits after prune has chosen ids and before it deletes them.
        app(OutboxStoreRepository::class)->replayLegacy(ids: [$id]);
        $statusAtDelete = Outbox::query()->whereKey($id)->value('status');
        $deleteSql = $query;
    });

    $deleted = app(OutboxStoreRepository::class)->pruneCompletedBefore(threshold: Carbon::now()->subDays(30));

    expect($statusAtDelete)->toBe('pending', 'replay did not land before the delete; sql='.$deleteSql)
        ->and($deleted)->toBe(0)
        ->and(Outbox::query()->whereKey($id)->exists())->toBeTrue()
        ->and(Outbox::query()->whereKey($id)->value('status'))->toBe('pending');
});
